def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm followed
    by Reverse Polish Notation (RPN) evaluation, which respects operator precedence 
    and handles parentheses and floating-point numbers.
    """

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def infix_to_postfix(expression):
        output = []
        operators = []
        i = 0

        while i < len(expression):
            char = expression[i]

            if char.isdigit() or char == '.':
                num = ''
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                output.append(float(num))
                continue

            if char == ' ':
                i += 1
                continue

            if char in '()':
                if char == '(':
                    operators.append(char)
                else:
                    while operators and operators[-1] != '(':
                        output.append(operators.pop())
                    operators.pop()  # Pop the '('
            elif char in "+-*/":
                while (operators and precedence(operators[-1]) >= precedence(char)):
                    output.append(operators.pop())
                operators.append(char)
            i += 1

        while operators:
            output.append(operators.pop())

        return output

    def evaluate_rpn(postfix):
        stack = []

        for token in postfix:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)

        return stack[0]

    postfix_expr = infix_to_postfix(expr)
    return evaluate_rpn(postfix_expr)
